script:
// Excel 导出 - 自定义列顺序示例
// 查询数据
var data = db.select("select id, username, email, phone, create_time from sys_user where is_del = 0 limit 10")

// 定义列顺序（按这个顺序输出）
var columnOrder = ["username", "email", "phone", "create_time"]

// 定义表头映射
var headers = {
    "username": "用户名",
    "email": "邮箱",
    "phone": "手机号",
    "create_time": "创建时间"
}

// 导出 Excel
var excelBytes = excel.write(data, columnOrder, headers)

// 设置响应头
response.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")
response.setHeader("Content-Disposition", "attachment;filename=" + URLEncoder.encode("用户导出_" + System.currentTimeMillis() + ".xlsx", "UTF-8"))
response.write(excelBytes)
